function valcheckType(form){
                                                        if (form.module_type.value == 'S'){
                                                                return true;
                                                        }
                                                    return false;
                                                    }
                                                    function typeChanged(moduleType){
                                                        if (moduleType.value == 'M'){
                                                                var form = moduleType.form;
                                                                form.parent_module_id.value = '';
                                                                form.parent_code.value = '';
                                                                form.parent_desc.value = '';
                                                                document.getElementById('lbparent_desc').innerHTML = '';
                                                        }
                                                }

function itemChange(triggerBy){
                if(triggerBy.value == 'completedBySO'){
                    $('#pSurveyor_row').css('display', 'flex');
                    $('#pProvider_row').css('display', 'flex');
                    $('#pCategory_row').css('display', 'flex');
                    $('#pQualityLevel_row').css('display', 'flex');
                    $('#pOfficer_row').css('display', 'none');
                    $('#search_pOfficer').val('');
                } else if(triggerBy.value == 'jobsByOfficer' || triggerBy.value == 'outstandingJob'){
                    $('#pSurveyor_row').css('display', 'none');
                    $('#pProvider_row').css('display', 'none');
                    $('#pCategory_row').css('display', 'none');
                    $('#pQualityLevel_row').css('display', 'none');
                    $('#search_pOfficer').val('');
                    $('#search_pProvider').val('');
                    $('#search_pCategory').val('');
                    $('#search_pQualityLevel').val('');
                    $('#pOfficer_row').css('display', 'flex');
                } else if(triggerBy.value == 'completedJob' || triggerBy.value == 'kivJob' || triggerBy.value == 'queryJob'){
                    $('#pSurveyor_row').css('display', 'none');
                    $('#pProvider_row').css('display', 'none');
                    $('#pCategory_row').css('display', 'none');
                    $('#pQualityLevel_row').css('display', 'none');
                    $('#pOfficer_row').css('display', 'none');
                    $('#search_pOfficer').val('');
                    $('#search_pProvider').val('');
                    $('#search_pCategory').val('');
                    $('#search_pQualityLevel').val('');
                    $('#search_pOfficer').val('');
                }else{
                } 
                }

